const vals=[]; const re=/children:\"((?:["'^"'"\\\\]|\\\\.)*)\"/g; let m; while((m=re.exec(x))) { let v; try{v=JSON.parse('\"'+m[1]+'\"')}catch{v=m[1]} if(v.trim()) vals.push(v); }
for(const v of vals) console.log(v);
console.error('count',vals.length,'range',a,b)
NODE"

